const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const thailand = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Thailand'))
    .geometry();

  const baselineStartDate = '2001-01-01';
  const baselineEndDate = '2010-12-31';
  const comparisonDateStart = '2016-04-01';
  const comparisonDateEnd = '2016-04-30';
  const month = 4; // April

  // 2. Data Acquisition & Pre-processing Function
  const modisLst = ee.ImageCollection('MODIS/061/MOD11A1');

  const processLst = function(image) {
    const quality = image.select('QC_Day');
    // Bits 0-1: Mandatory QA flags. 00 = Good data.
    const qaMask = quality.bitwiseAnd(0b11).eq(0);
    const lst = image.select('LST_Day_1km')
      .updateMask(qaMask)
      .multiply(0.02) // Apply scale factor for Kelvin
      .subtract(273.15); // Convert to Celsius
    return lst.copyProperties(image, ['system:time_start']);
  };

  // 3. Processing and Checks
  const baselineCollection = modisLst
    .filterDate(baselineStartDate, baselineEndDate)
    .filter(ee.Filter.calendarRange(month, month, 'month'))
    .map(processLst);

  const comparisonCollection = modisLst
    .filterDate(comparisonDateStart, comparisonDateEnd)
    .map(processLst);

  const baselineSize = baselineCollection.size().getInfo();
  const comparisonSize = comparisonCollection.size().getInfo();

  if (baselineSize === 0 || comparisonSize === 0) {
    console.log(`Baseline (2001-2010) image count: ${baselineSize}`);
    console.log(`Comparison (2016) image count: ${comparisonSize}`);
    console.log('C1: Empty Collection');
    return;
  }

  const baselineMeanImage = baselineCollection.mean();
  const comparisonMeanImage = comparisonCollection.mean();

  // 4. Calculation
  const scale = 3000;
  const baselineStats = baselineMeanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: thailand,
    scale: scale,
    maxPixels: 1e9
  });

  const comparisonStats = comparisonMeanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: thailand,
    scale: scale,
    maxPixels: 1e9
  });

  const baselineTemp = baselineStats.get('LST_Day_1km_mean').getInfo();
  const baselinePixels = baselineStats.get('LST_Day_1km_count').getInfo();

  const comparisonTemp = comparisonStats.get('LST_Day_1km_mean').getInfo();
  const comparisonPixels = comparisonStats.get('LST_Day_1km_count').getInfo();

  // 5. Validation & Final Answer
  console.log(`Baseline April LST (2001-2010): ${baselineTemp ? baselineTemp.toFixed(2) : 'N/A'} C`);
  console.log(`Baseline valid pixel count: ${baselinePixels}`);
  console.log(`Comparison April LST (2016): ${comparisonTemp ? comparisonTemp.toFixed(2) : 'N/A'} C`);
  console.log(`Comparison valid pixel count: ${comparisonPixels}`);

  if (baselinePixels === 0 || comparisonPixels === 0) {
    console.log('C2: No Valid Pixels');
    return;
  }

  if (baselineTemp === null || comparisonTemp === null) {
    console.log('C3: Calculation Failure');
    return;
  }

  if (comparisonTemp > baselineTemp) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during EE initialization or analysis: ${e}`);
    console.log('D');
  }
}

initEE();
